int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    unordered_map<long long, long long> freq;  // value -> occurrences so far
    freq.reserve(n * 2);
    long long ans = 0;
    auto look = [&](long long v) {
        auto it = freq.find(v);
        if (it != freq.end()) ans += it->second;
    };
    for (int k = 0; k < n; k++) {
        long long self;
        scanf("%lld", &self);
        string s = to_string(self);
        look(self);
        int d = s.size();
        // distinct swaps of unequal digits give pairwise distinct strings, so no dedup is needed
        for (int i = 0; i < d; i++)
            for (int j = i + 1; j < d; j++) {
                if (s[i] == s[j] || (i == 0 && s[j] == '0')) continue;
                swap(s[i], s[j]);
                look(stoll(s));
                swap(s[i], s[j]);
            }
        freq[self]++;
    }
