import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = (int) readLong(in);
        HashMap<Long, Integer> freq = new HashMap<>(n * 2);  // value -> occurrences so far
        long ans = 0;
        for (int k = 0; k < n; k++) {
            long self = readLong(in);
            char[] c = Long.toString(self).toCharArray();
            Integer f = freq.get(self);
            if (f != null) ans += f;
            int d = c.length;
            // distinct swaps of unequal digits give pairwise distinct strings, so no dedup is needed
            for (int i = 0; i < d; i++)
                for (int j = i + 1; j < d; j++) {
                    if (c[i] == c[j] || (i == 0 && c[j] == '0')) continue;
                    char t = c[i]; c[i] = c[j]; c[j] = t;
                    long v = 0;
                    for (char ch : c) v = v * 10 + (ch - '0');
                    f = freq.get(v);
                    if (f != null) ans += f;
                    t = c[i]; c[i] = c[j]; c[j] = t;
                }
            freq.merge(self, 1, Integer::sum);
        }
        System.out.println(ans);
    }

    static long readLong(DataInputStream in) throws IOException {
        int c = in.read();
        while (c != '-' && (c < '0' || c > '9')) c = in.read();
        boolean neg = c == '-';
        if (neg) c = in.read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = in.read(); }
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	freq := make(map[int64]int64, n) // value -> occurrences so far
	var ans int64
	for k := 0; k < n; k++ {
		sc.Scan()
		self, _ := strconv.ParseInt(sc.Text(), 10, 64)
		c := []byte(strconv.FormatInt(self, 10))
		ans += freq[self]
		d := len(c)
		// distinct swaps of unequal digits give pairwise distinct strings, so no dedup is needed
		for i := 0; i < d; i++ {
			for j := i + 1; j < d; j++ {
				if c[i] == c[j] || (i == 0 && c[j] == '0') {
					continue
				}
				c[i], c[j] = c[j], c[i]
				var v int64
				for _, ch := range c {
					v = v*10 + int64(ch-'0')
				}
				ans += freq[v]
				c[i], c[j] = c[j], c[i]
			}
		}
		freq[self]++
	}
	fmt.Println(ans)
}
